import { createStep, createWorkflow } from '@mastra/core/workflows';
import { z } from 'zod';

const QuoteInputSchema = z.object({
  quoteId: z.string(),
  tenantId: z.string(),
  discountPercent: z.number().min(0).max(50),
  totalVnd: z.number().positive(),
});

const validateDiscountStep = createStep({
  id: 'validate-discount',
  inputSchema: QuoteInputSchema,
  outputSchema: QuoteInputSchema.extend({ requiresManagerSignoff: z.boolean() }),
  execute: async ({ inputData }) => ({
    ...inputData,
    requiresManagerSignoff: inputData.discountPercent > 10,
  }),
});

const managerApprovalStep = createStep({
  id: 'manager-approval',
  inputSchema: QuoteInputSchema.extend({ requiresManagerSignoff: z.boolean() }),
  outputSchema: z.object({
    quoteId: z.string(),
    approved: z.boolean(),
    approverId: z.string(),
  }),
  suspendSchema: z.object({
    quoteId: z.string(),
    reason: z.string(),
    requestedAt: z.string(),
  }),
  resumeSchema: z.object({
    approved: z.boolean(),
    approverId: z.string(),
  }),
  execute: async ({ inputData, resumeData, suspend }) => {
    if (!inputData.requiresManagerSignoff) {
      return { quoteId: inputData.quoteId, approved: true, approverId: 'AUTO_POLICY' };
    }
    if (!resumeData) {
      // Tạm dừng workflow bền bỉ và bắn thông báo ZaloBot kèm runId cho Giám đốc
      await suspend({
        quoteId: inputData.quoteId,
        reason: `Chiết khấu ${inputData.discountPercent}% vượt ngưỡng 10% chuẩn CRM`,
        requestedAt: new Date().toISOString(),
      });
    }
    return {
      quoteId: inputData.quoteId,
      approved: resumeData!.approved,
      approverId: resumeData!.approverId,
    };
  },
});

export const crmQuoteApprovalWorkflow = createWorkflow({
  id: 'crm-quote-approval',
  inputSchema: QuoteInputSchema,
  outputSchema: z.object({ quoteId: z.string(), approved: z.boolean(), approverId: z.string() }),
})
  .then(validateDiscountStep)
  .then(managerApprovalStep)
  .commit();

// Minh họa chạy từ API Next.js và khôi phục khi nhận webhook ZaloBot
export async function demoLifecycle() {
  const run = await crmQuoteApprovalWorkflow.createRun();
  const initial = await run.start({
    inputData: { quoteId: 'BG-2026-409', tenantId: 'f1-tunglong', discountPercent: 14, totalVnd: 1850000000 },
  });
  if (initial.status === 'suspended') {
    const finalized = await run.resume({
      step: 'manager-approval',
      resumeData: { approved: true, approverId: 'gd-kinhdoanh-01' },
    });
    console.log('Kết quả chốt báo giá:', finalized.status);
  }
}
